const c=(id:string,title:string,description:string,requires:string[],teaches:string[],paragraphs:string[],rules:string[],examples:{problem:string;steps:string[]}[],misconception:string,questions:MathQuestion[],review:MathQuestion[])=>chapter(id,title,description,[lesson({id:`${id}-lesson`,title,requires,teaches,paragraphs,rules,examples,misconception,questions})],review);

const classes=c("mpt-classes","Designing a Class","Move from local variables to objects that preserve related state and behavior.",["java-foundations"],["class-design","instance-fields","instance-methods"],["A class is a blueprint for objects. Instance fields store the state belonging to each object; instance methods read or change that state. A useful class represents one coherent idea rather than an unrelated pile of variables.","Every object created with new receives its own instance-field values. A method call such as account.deposit(20) selects one object and runs behavior using that object's state."],["Declare instance fields inside the class but outside methods.","Use new to construct an object.","An instance method can access the receiving object's fields."],[{problem:"Model a counter with a value and an increment operation.",steps:["Store value as an instance field.","Make increment add one to that field."]},{problem:"Create two Counter objects.",steps:["Each new Counter() is a separate object.","Incrementing one does not change the other's value."]}],"A class variable declaration describes state; it does not create an object by itself.",[code("mpt-cl-1","Inside a class, declare a private integer instance field named score.","private int score;","java","Write a field declaration, not a local variable.",["Use the access modifier, type, name, and semicolon."]),code("mpt-cl-2","Write one statement that creates a Player object and stores its reference in a variable named player.","Player player = new Player();","java","The type and constructor name match.",["Declare the reference and call the constructor."]),code("mpt-cl-3","Write an instance method named addPoint that returns nothing and increases score by 1.","public void addPoint() { score++; }","java","The method changes the object's field.",["Use void and update score inside the body."]),output("mpt-cl-4","Two Counter objects begin at 0. The first is incremented twice and the second once. What values are printed for first, then second?","2, 1",["2, 1","3, 3","2, 2","1, 2"],"Each object owns separate state.",["The operations are applied to different receivers."]),pick("mpt-cl-5","Which member belongs separately to every object?","An instance field",["An instance field","A static field","The class name","An import"],"Look for state tied to one instance.",["Instance fields are stored per object."])],[code("mpt-cl-r1","Declare a private String field named title.","private String title;","java","Use a field declaration.",["The declaration belongs in the class body."]),code("mpt-cl-r2","Create a Book object in a variable named book.","Book book = new Book();","java","Call the matching constructor.",["Type, variable, new, and constructor are required."]),pick("mpt-cl-r3","If two objects have different field values, changing one object's field does what to the other?","Nothing",["Changes it too","Nothing","Deletes it","Makes the field static"],"The objects have independent instance state.",["Only the receiving object changes."])]);

const constructors=c("mpt-constructors","Constructors, Parameters & Scope","Create valid objects and track which name each statement refers to.",["class-design"],["constructors","this-reference","object-parameters"],["A constructor establishes an object's starting state. It has the class name and no return type. Parameters supply caller-provided values; this.field distinguishes an instance field from a parameter with the same name.","Java passes object references by value. A method receives its own copy of the reference, so it can mutate the referenced object, but reassigning the parameter does not redirect the caller's variable."],["A constructor has no return type, not even void.","Use this.name to select the current object's field.","Parameter reassignment and object mutation are different operations."],[{problem:"Construct a Player from a name.",steps:["Accept String name in the constructor.","Assign this.name = name."]},{problem:"Pass an object to a method that changes one of its fields.",steps:["Both references initially select the same object.","The mutation is visible through either reference."]}],"Writing void before a constructor turns it into an ordinary method and leaves the default construction behavior unchanged.",[code("mpt-co-1","Write the constructor header and body for Player(String name) that assigns the parameter to the field name.","public Player(String name) { this.name = name; }","java","The constructor name must match the class.",["Use this.name for the field and name for the parameter."]),pick("mpt-co-2","Which declaration is a constructor for class Box?","public Box(int size)",["public void Box(int size)","public Box(int size)","public int Box()","void Box()"],"Constructors have no return type.",["The class name is Box and no return type appears."]),code("mpt-co-3","Inside a constructor with parameter int capacity, assign it to the instance field capacity.","this.capacity = capacity;","java","Distinguish field from parameter.",["this.capacity selects the field."]),pick("mpt-co-4","A method parameter refers to an object and changes that object's field. Can the caller observe the field change?","Yes",["Yes","No","Only if the parameter is static","Only for primitive fields"],"Both references can select the same object.",["Mutating the shared object is observable."]),pick("mpt-co-5","A local variable and an instance field share a name. Which syntax explicitly selects the field?","this.name",["name.this","this.name","class.name","new.name"],"Use the current-object reference.",["this names the receiving object."])],[code("mpt-co-r1","Write a no-argument constructor for class Lamp that sets on to false.","public Lamp() { on = false; }","java","No return type appears.",["Use the class name and empty parameter list."]),pick("mpt-co-r2","What is the scope of a constructor parameter?","The constructor body",["The whole project","The constructor body","Every object","Only the caller"],"A parameter is local to the invoked constructor.",["Its name is available inside that body."]),code("mpt-co-r3","Create a Student with constructor argument \"Mia\" and store it in student.","Student student = new Student(\"Mia\");","java","Pass the String to new Student.",["The declaration and constructor call form one statement."])]);

const encapsulation=c("mpt-encapsulation","Encapsulation & Class Invariants","Protect state by routing changes through meaningful operations.",["constructors","instance-methods"],["encapsulation","accessors-mutators","invariants"],["Encapsulation hides representation details and exposes a controlled public interface. Private fields prevent unrelated code from placing an object into an invalid state. Methods can validate a proposed change before committing it.","An invariant is a condition that should remain true for every valid object, such as balance≥0. Constructors and mutating methods share responsibility for preserving it. Tests should probe boundary values as well as ordinary valid updates."],["Keep representation fields private unless exposure is intentional.","Getters report state; mutators enforce rules before changing it.","Every public operation must preserve the class invariant."],[{problem:"Prevent a temperature below an allowed minimum.",steps:["Keep temperature private.","Validate the new value in the setter before assignment."]},{problem:"Expose a balance without allowing direct assignment.",steps:["Provide a getter.","Do not provide an unrestricted public field."]}],"Private does not make data magically valid; the constructor and methods still need to enforce the rules.",[code("mpt-en-1","Write a getter named getScore that returns the private int field score.","public int getScore() { return score; }","java","A getter returns the field without changing it.",["Use return score."]),code("mpt-en-2","Write a method deposit(int amount) that adds amount to balance only when amount is positive.","public void deposit(int amount) { if (amount > 0) { balance += amount; } }","java","Guard the update with a condition.",["Only the positive branch mutates balance."]),pick("mpt-en-3","Why keep balance private?","To control how it changes",["To make arithmetic faster","To control how it changes","To create more objects","To avoid constructors"],"Think about preserving valid state.",["Public methods can validate every change."]),pick("mpt-en-4","Which operation threatens the invariant size>=0?","Assigning -1 directly to size",["Reading size","Assigning -1 directly to size","Returning size","Printing size"],"An invariant is broken by an invalid mutation.",["A negative assignment violates the condition."]),code("mpt-en-5","Declare a private double field named price.","private double price;","java","Hide the representation field.",["Use private, double, the name, and a semicolon."])],[pick("mpt-en-r1","Which class design best preserves a nonnegative balance?","Private balance with validated methods",["Public balance field","Private balance with validated methods","No constructor","Only static methods"],"Route changes through controlled behavior.",["The class can reject invalid updates."]),code("mpt-en-r2","Write a boolean method named isEmpty that returns whether size equals 0.","public boolean isEmpty() { return size == 0; }","java","Return the comparison directly.",["The comparison already produces a boolean."]),pick("mpt-en-r3","Who must preserve an invariant?","Every constructor and mutating public method",["Only getters","Only main","Every constructor and mutating public method","The compiler alone"],"Consider every route that changes state.",["All state-changing entry points must protect it."])]);

const staticAggregation=c("mpt-static-aggregation","Static Members, Aggregation & UML","Separate class-wide state from per-object state and build objects from collaborating parts.",["encapsulation"],["static-members","aggregation","uml-basics"],["A static member belongs to the class as a whole. Use it for information genuinely shared across all instances, such as a count of constructed objects. Instance members remain the default for state that differs per object.","Aggregation models a has-a relationship: a Course can contain a Teacher reference. UML class diagrams summarize names, fields, methods, visibility, and relationships before implementation."],["Access static members through the class name.","Use aggregation for has-a; inheritance for is-a.","A UML minus sign commonly means private; plus means public."],[{problem:"Count all created Player objects.",steps:["Declare a private static int count.","Increment it in every constructor."]},{problem:"Model a Car with an Engine.",steps:["Store an Engine field in Car.","Construct or receive the Engine through a constructor."]}],"Making a field static to share it accidentally makes every object observe the same value.",[code("mpt-sa-1","Declare a private static integer field named count initialized to 0.","private static int count = 0;","java","Static appears between the access modifier and type.",["This creates one class-wide integer."]),code("mpt-sa-2","Write one statement that calls the static method reset on class Scoreboard.","Scoreboard.reset();","java","Use the class name as receiver.",["Static behavior belongs to Scoreboard itself."]),pick("mpt-sa-3","A Car stores an Engine object. What relationship is this?","Aggregation",["Inheritance","Aggregation","Overloading","Recursion"],"Car has an Engine.",["Has-a is aggregation."]),pick("mpt-sa-4","In common UML notation, what does -balance mean?","A private field named balance",["A negative value","A private field named balance","A deleted method","A static constructor"],"The symbol describes visibility.",["Minus indicates private visibility."]),pick("mpt-sa-5","Which field should usually be static?","The number of objects created",["Each player's score","Each book's title","The number of objects created","Each account's balance"],"Choose genuinely shared class-wide state.",["One count is shared across all instances."])],[code("mpt-sa-r1","Declare a private Engine field named engine inside Car.","private Engine engine;","java","The field type is another class.",["This represents the has-a relationship."]),pick("mpt-sa-r2","Which access style is clearest for a static field count?","Player.count",["this.count","Player.count","new count","count.Player"],"Name the owning class.",["Static members belong to the class."]),pick("mpt-sa-r3","A Student is a Person. Which relationship fits?","Inheritance",["Aggregation","Inheritance","Recursion","Exception handling"],"The phrase is-a is the clue.",["A subtype relationship models is-a."])]);

const inheritance=c("mpt-inheritance","Inheritance & Constructor Chaining","Reuse a valid abstraction while making subtype responsibilities explicit.",["aggregation","constructors"],["inheritance","super-calls","protected-contracts"],["Inheritance defines an is-a relationship. A subclass receives accessible superclass behavior and can add specialized state or methods. Reuse is valuable only when every subclass object truly satisfies the superclass contract.","A subclass constructor must initialize the superclass portion. Java inserts super() when possible; otherwise call a matching superclass constructor explicitly as the first constructor statement."],["Use extends for one class to inherit from another.","A super(...) constructor call must be first.","Private superclass fields remain private; use protected/public behavior intentionally."],[{problem:"Model SavingsAccount as an Account.",steps:["Declare class SavingsAccount extends Account.","Call super with the initial balance."]},{problem:"Decide between Car extends Engine and Car has Engine.",steps:["A Car is not an Engine.","Use aggregation rather than inheritance."]}],"Inheritance is not a general-purpose way to access another class's fields; the semantic is-a relationship comes first.",[code("mpt-in-1","Write the class header declaring Dog as a subclass of Animal.","public class Dog extends Animal { }","java","Use extends between class names.",["Dog inherits accessible Animal members."]),code("mpt-in-2","Inside a subclass constructor, call the superclass constructor with argument name.","super(name);","java","The call must be first in the constructor.",["Use super with the required argument."]),pick("mpt-in-3","Which statement is true about a private superclass field?","The subclass cannot access it directly",["The subclass can always access it directly","The subclass cannot access it directly","It becomes static","It is copied into main"],"Private visibility remains enforced.",["Use superclass methods to interact with private state."]),pick("mpt-in-4","Which relationship supports inheritance?","A Circle is a Shape",["A Car has an Engine","A Circle is a Shape","A Library has Books","A Team has Players"],"Look for is-a.",["Circle can satisfy a Shape contract."]),pick("mpt-in-5","Where must super(...) appear in a constructor?","As the first statement",["Anywhere","As the first statement","After return","Outside the constructor"],"Superclass initialization precedes subclass initialization.",["Java requires it first."])],[code("mpt-in-r1","Declare Manager as a subclass of Employee.","public class Manager extends Employee { }","java","Use an is-a relationship.",["The extends clause names Employee."]),pick("mpt-in-r2","What happens before subclass fields finish initialization?","The superclass constructor runs",["main ends","The superclass constructor runs","All methods become static","The object is deleted"],"Build the inherited portion first.",["Constructor chaining initializes from superclass to subclass."]),pick("mpt-in-r3","A House contains Rooms. Prefer:","Aggregation",["Inheritance","Aggregation","Overriding","Recursion"],"A House is not a Room.",["The relationship is has-a."])]);

const polymorphism=c("mpt-polymorphism","Overriding, Overloading & Dynamic Binding","Predict which method signature is selected and which implementation runs.",["inheritance","methods"],["overriding","overloading","polymorphism","dynamic-binding"],["Overriding replaces inherited behavior with the same method signature in a subclass. Dynamic binding chooses the implementation from the actual object at runtime, even when the reference type is a superclass.","Overloading creates multiple methods with the same name but different parameter lists. The compiler selects an overload from argument types; overriding and overloading solve different problems."],["Override: same signature across superclass and subclass.","Overload: same name, different parameter list.","A superclass reference can call only members promised by its declared type, while overridden behavior comes from the actual object."],[{problem:"Animal a=new Dog(); a.speak();",steps:["The reference type allows speak because Animal declares it.","The Dog override runs because the object is a Dog."]},{problem:"Define print(int) and print(String).",steps:["The parameter lists differ.","This is overloading, selected at compile time."]}],"The reference type controls what calls are legal; the object type controls which override executes.",[code("mpt-po-1","Write an override of public String sound() that returns \"bark\".","@Override public String sound() { return \"bark\"; }","java","Keep the same signature and add the annotation.",["The subclass method returns its specialized result."]),pick("mpt-po-2","Animal a=new Dog(); a.speak(); Dog overrides speak. Which version runs?","Dog.speak",["Animal.speak","Dog.speak","Both","Neither"],"Use the actual object type for an override.",["Dynamic binding selects Dog.speak."]),pick("mpt-po-3","Methods save(int x) and save(String x) demonstrate:","Overloading",["Overriding","Overloading","Aggregation","Recursion"],"The name is shared but parameters differ.",["Different parameter lists create overloads."]),pick("mpt-po-4","A Shape reference holds a Circle. Can it directly call a method declared only in Circle?","No",["Yes","No","Only if static","Only in a constructor"],"The declared reference type controls accessible members.",["Shape does not promise Circle-only behavior."]),pick("mpt-po-5","What does @Override help the compiler verify?","That a matching inherited method exists",["That the method is static","That a matching inherited method exists","That no object is created","That every field is public"],"It checks the intended relationship.",["A signature mistake becomes a compile error."])],[pick("mpt-po-r1","Same signature in a subclass is:","Overriding",["Overloading","Overriding","Aggregation","Shadowing only"],"Compare the signatures.",["The subclass replaces inherited behavior."]),pick("mpt-po-r2","Same name with different parameters is:","Overloading",["Overloading","Overriding","Inheritance only","An exception"],"The parameter list distinguishes methods.",["The compiler selects among overloads."]),output("mpt-po-r3","Animal a=new Dog(); Dog.speak prints Dog. What prints when a.speak() runs?","Dog",["Animal","Dog","AnimalDog","Nothing"],"Use dynamic binding.",["The actual object is Dog."])]);

const objectMethods=c("mpt-object-methods","Object Methods, Equality & Copying","Define meaningful text, equality, and copy behavior for user-defined objects.",["polymorphism","encapsulation"],["object-methods","equals-contract","copying-objects","string-builders"],["Every class ultimately inherits methods from Object. Override toString to provide useful text and equals to define value equality. The equals contract requires reflexive, symmetric, transitive, consistent behavior and false for null.","Assignment copies a reference, not an object. A deliberate copy constructor or copy method can create a separate object. StringBuilder efficiently accumulates many text changes without creating a new String for each step."],["== compares object references; equals can compare logical values.","Override hashCode whenever equals is overridden for hashed collections.","A copy must decide whether referenced fields are shared or duplicated."],[{problem:"Compare two distinct Point objects with equal coordinates.",steps:["== is false because references differ.","A coordinate-based equals method can return true."]},{problem:"Build a long report in a loop.",steps:["Create one StringBuilder.","Append pieces, then call toString once."]}],"An equals method with the wrong parameter type overloads rather than overrides Object.equals.",[code("mpt-om-1","Write a toString override for a class with field name that returns the name.","@Override public String toString() { return name; }","java","Return a String representation.",["Keep the no-argument signature."]),pick("mpt-om-2","For two separately constructed objects with equal fields, what does == compare?","Whether the references select the same object",["All fields","Whether the references select the same object","Their toString values","Their class names only"],"Reference equality is different from value equality.",["== checks identity for object references."]),code("mpt-om-3","Create a StringBuilder variable named builder initialized empty.","StringBuilder builder = new StringBuilder();","java","Construct the mutable text builder.",["Declare the reference and call its constructor."]),code("mpt-om-4","Append the String value name to builder.","builder.append(name);","java","Use the append method on the existing builder.",["The builder mutates and returns itself."]),pick("mpt-om-5","Why pair hashCode with equals?","Equal objects must work consistently in hashed collections",["To make fields public","Equal objects must work consistently in hashed collections","To avoid constructors","To enable recursion"],"Collections depend on both contracts.",["Equal objects must have equal hash codes."])],[pick("mpt-om-r1","Which operation copies only a reference?","Point b = a;",["Point b = new Point(a);","Point b = a;","a.toString();","a.equals(b);"],"No new object appears.",["Both variables select the same Point."]),code("mpt-om-r2","Convert builder to an immutable String and store it in result.","String result = builder.toString();","java","Call the conversion method.",["The returned String is stored separately."]),pick("mpt-om-r3","Which method supplies an object's human-readable representation?","toString",["equals","toString","hashCode only","main"],"It is used during string conversion and printing.",["Override toString for useful text."])]);

const exceptions=c("mpt-exceptions","Exceptions, Assertions & Debugging","Separate recoverable failures from violated assumptions and use evidence to locate defects.",["methods","inheritance"],["exceptions","try-catch","throwing","assertions","debugging-strategy"],["An exception transfers control when normal execution cannot continue. Put only the risky operation in a try block, catch exceptions you can handle meaningfully, and use finally for cleanup that must occur either way.","Assertions document internal assumptions during development; they are not a substitute for validating public input. Debugging is an evidence process: reproduce the failure, reduce the case, inspect state, form a hypothesis, and retest."],["Catch specific exceptions before broader ones.","Use throw to signal a detected problem; throws declares propagation.","Validate external input explicitly; reserve assertions for programmer assumptions."],[{problem:"Reject a negative deposit.",steps:["Check the amount at the method boundary.","Throw IllegalArgumentException with a useful message."]},{problem:"Investigate a wrong loop result.",steps:["Use the smallest failing input.","Inspect the loop invariant and boundary values."]}],"Catching Exception and doing nothing hides the failure; it does not make the program reliable.",[code("mpt-ex-1","Write one statement that throws IllegalArgumentException with message \"negative\".","throw new IllegalArgumentException(\"negative\");","java","Construct and throw the exception.",["The throw statement ends with a semicolon."]),pick("mpt-ex-2","Which block runs whether or not a caught exception occurs?","finally",["try","catch","finally","throw"],"It is intended for cleanup.",["finally runs after try/catch completion."]),pick("mpt-ex-3","Which is the best first debugging step?","Reproduce the failure with a known input",["Rewrite everything","Reproduce the failure with a known input","Add random changes","Catch every exception"],"Start from evidence.",["A repeatable failure supports controlled investigation."]),pick("mpt-ex-4","Assertions are best for:","Internal conditions that should be impossible to violate",["All user input validation","Internal conditions that should be impossible to violate","Replacing tests","Printing normal output"],"They express programmer assumptions.",["Assertions may be disabled and are not public validation."]),code("mpt-ex-5","Write a catch header that handles NumberFormatException in variable ex.","catch (NumberFormatException ex) { }","java","Name the exception type and variable.",["The catch body follows the parenthesized parameter."])],[pick("mpt-ex-r1","What should a catch block do?","Handle or deliberately propagate the problem",["Always ignore it","Handle or deliberately propagate the problem","Restart the computer","Change every field"],"Reliability requires an intentional response.",["Silent swallowing loses evidence."]),code("mpt-ex-r2","Declare that method read may propagate IOException. Write only the method header for public void read().","public void read() throws IOException","java","Use throws in the declaration.",["The declaration names the possible exception."]),pick("mpt-ex-r3","Which tool records an internal assumption during development?","assert",["assert","println only","new","extends"],"It checks a condition expected to be true.",["Assertions expose violated invariants."])]);

const abstraction=c("mpt-abstraction","Abstract Classes & Interfaces","Program against stable capabilities while allowing multiple implementations.",["inheritance","polymorphism"],["abstract-classes","interfaces","interface-polymorphism"],["An abstract class can hold shared state and implemented behavior while leaving selected methods abstract. It cannot be instantiated directly. An interface specifies capabilities that otherwise unrelated classes can implement.","Depending on an interface reduces coupling: a method that accepts List can work with multiple list implementations. The caller needs the promised operations, not the representation."],["Abstract methods have declarations but no body.","A class extends one class and may implement multiple interfaces.","Prefer the least-specific type that provides the operations you need."],[{problem:"Represent shapes with a required area operation.",steps:["Declare abstract class Shape.","Declare abstract double area(); and implement it in each concrete shape."]},{problem:"Allow different objects to be printable.",steps:["Declare a Printable interface.","Accept Printable references where only print behavior is needed."]}],"An interface is a contract, not an object; instantiate a concrete implementing class.",[code("mpt-ab-1","Declare an interface named Payable with method double amount().","public interface Payable { double amount(); }","java","Interface methods declare required behavior.",["The method has no implementation body here."]),code("mpt-ab-2","Write the class header declaring Invoice implements Payable.","public class Invoice implements Payable { }","java","Use implements for an interface.",["Invoice promises to supply Payable behavior."]),pick("mpt-ab-3","Can an abstract class be instantiated directly?","No",["Yes","No","Only with static","Only in main"],"It may contain unfinished abstract behavior.",["Construct a concrete subclass instead."]),pick("mpt-ab-4","Why accept an interface parameter?","To allow any implementation of the required capability",["To expose private fields","To allow any implementation of the required capability","To avoid methods","To force one concrete class"],"Depend on the contract.",["Multiple implementations can be substituted."]),code("mpt-ab-5","Declare an abstract public method named area returning double with no parameters.","public abstract double area();","java","An abstract method ends with a semicolon.",["No method body is supplied."])],[pick("mpt-ab-r1","Which keyword connects a class to an interface?","implements",["extends only","implements","throws","new"],"A class fulfills the interface contract.",["Use implements."]),code("mpt-ab-r2","Declare abstract class Shape with no members.","public abstract class Shape { }","java","Place abstract before class.",["The class cannot be directly instantiated."]),pick("mpt-ab-r3","A parameter needs only compareTo behavior. Prefer which type?","The interface that promises compareTo",["Object always","The interface that promises compareTo","One unrelated concrete class","A public field"],"Use the narrow stable contract.",["This keeps the method reusable."])]);

const recursion=c("mpt-recursion","Recursion & Call-Stack Reasoning","Design a shrinking subproblem and trace the pending work on the call stack.",["methods","conditionals"],["recursion","base-cases","recursive-tracing"],["A recursive method solves a problem by calling itself on a smaller instance. The base case stops the chain; the recursive case must move toward it. Each call has its own parameters and local variables on the call stack.","Tracing separates descent from return. For factorial(3), calls descend to factorial(1), then pending multiplications complete as values return. Write the mathematical recurrence before coding when possible."],["Every recursive path needs a reachable base case.","The recursive argument must make measurable progress.","Each call owns a separate local state frame."],[{problem:"Compute factorial recursively.",steps:["Base case: n≤1 returns 1.","Recursive case: return n*factorial(n-1)."]},{problem:"Trace sum(3) where sum(n)=n+sum(n-1).",steps:["Descend 3→2→1→0.","Return 0,1,3,6."]}],"Having a base case in the source is insufficient if the recursive arguments never reach it.",[code("mpt-re-1","Write a recursive factorial method for nonnegative int n, using n<=1 as the base case.","public static int factorial(int n) { if (n <= 1) { return 1; } return n * factorial(n - 1); }","java","Write the stopping case before the recursive return.",["The argument decreases by one."]),output("mpt-re-2","What does sum(3) return if sum(0)=0 and sum(n)=n+sum(n-1)?","6",["0","3","6","9"],"Expand calls until the base case.",["3+2+1+0=6."]),pick("mpt-re-3","What causes infinite recursion?","Recursive calls fail to reach a base case",["A method returns a value","Recursive calls fail to reach a base case","A field is private","A loop has one iteration"],"Check progress toward stopping.",["The call chain continues until stack exhaustion."]),output("mpt-re-4","Method f prints n, then calls f(n-1), stopping at 0. What prints for f(3)?","3 2 1",["1 2 3","3 2 1","3 3 3","0 1 2 3"],"Printing happens during descent.",["Each call prints before the next call."]),pick("mpt-re-5","Where are a recursive call's local variables stored?","In its own call-stack frame",["In every object","In its own call-stack frame","Only in the source file","In the compiler"],"Each active call needs separate state.",["The stack preserves pending calls."])],[output("mpt-re-r1","What is factorial(4)?","24",["4","10","16","24"],"Use 4*3*2*1.",["The recursion multiplies while returning."]),pick("mpt-re-r2","Which recursive call progresses toward zero?","count(n-1)",["count(n+1)","count(n)","count(n-1)","count(-n) always"],"Use a decreasing nonnegative measure.",["Subtracting one reaches the base case."]),code("mpt-re-r3","Write the base-case statement that returns 0 when n equals 0.","if (n == 0) { return 0; }","java","Use an equality comparison and return.",["This stops that path."])]);

const testing=c("mpt-testing","Testing Strategies & Testable Design","Choose cases that expose boundaries, state transitions, and failed assumptions.",["exceptions","invariants"],["unit-testing","test-drivers","boundary-testing","testable-design"],["A test has setup, an action, and an observable expectation. A test driver calls production code with deliberate cases; a test suite groups cases that cover normal behavior, boundaries, invalid input, and interactions.","Good tests are not just many examples. Partition the input space, test boundaries on both sides, and verify state after sequences of operations. Small deterministic methods are easier to test than code tied directly to input, time, or networking."],["Each test should state the behavior it protects.","Include normal, boundary, and invalid cases.","A regression test reproduces a previously fixed defect."],[{problem:"Test an age validator allowing 0 through 120.",steps:["Test 0 and 120 as valid boundaries.","Test -1 and 121 as immediately invalid neighbors."]},{problem:"Test a stack pop.",steps:["Push a known value.","Pop and verify both returned value and resulting size."]}],"A test that merely runs without crashing may miss a completely wrong result.",[pick("mpt-te-1","For valid range 1 through 10, which set best targets boundaries?","0, 1, 10, 11",["4, 5, 6","0, 1, 10, 11","1 only","100, 200"],"Test each boundary and its nearest outside value.",["These four values distinguish inclusion and rejection."]),pick("mpt-te-2","What makes a test an assertion rather than just an example run?","It compares the observed result with an expectation",["It uses println","It compares the observed result with an expectation","It creates many objects","It catches every exception"],"A test needs a verdict.",["The expected behavior is explicit."]),pick("mpt-te-3","What is a regression test?","A test preserving a previously fixed behavior",["A random test","A test preserving a previously fixed behavior","A performance guess","A compiler option"],"It prevents the same defect from returning.",["Keep the failing case after the fix."]),pick("mpt-te-4","Which design is easiest to test?","A method that receives inputs and returns a result",["A method that reads global input and exits","A method that receives inputs and returns a result","A method using random hidden state","One giant main method"],"Prefer explicit dependencies and observable results.",["Pure or controlled behavior is repeatable."]),code("mpt-te-5","Write one Java assertion verifying actual equals expected for primitive ints.","assert actual == expected;","java","Use the assert keyword and a boolean comparison.",["The assertion fails when values differ."])],[pick("mpt-te-r1","Which case is most important for a list removal method?","Removing from an empty list",["Only a middle element","Removing from an empty list","Printing the class name","Creating unrelated objects"],"Test a boundary where behavior changes.",["Empty-state handling often exposes defects."]),pick("mpt-te-r2","A test suite should include:","Normal, boundary, and invalid cases",["Only normal cases","Normal, boundary, and invalid cases","Only random values","No expected results"],"Map meaningful input partitions.",["Different classes of behavior need coverage."]),pick("mpt-te-r3","After fixing a bug, what should happen to the reproducing test?","Keep it in the suite",["Delete it","Keep it in the suite","Turn it into a comment","Run it only once"],"Protect against recurrence.",["It becomes a regression test."])]);

const multifile=c("mpt-multifile","Multi-File Programs, Packages & Build Boundaries","Organize cooperating classes without losing ownership or dependency clarity.",["class-design","interfaces"],["multi-file-programs","packages","dependency-boundaries"],["A maintainable program separates responsibilities across files and classes. A public top-level class normally matches its filename. Packages group related types and prevent name collisions; imports make external package names available without changing ownership.","Dependencies should point toward stable interfaces. Compile errors often reveal missing package declarations, wrong source roots, or filename/class mismatches rather than logic defects."],["Public top-level class Name belongs in Name.java.","Package declarations precede imports and class declarations.","Keep each class responsible for one coherent role."],[{problem:"Separate an order system.",steps:["Order stores order state; PriceCalculator computes totals.","Main wires objects together rather than owning every behavior."]},{problem:"Use class Scanner.",steps:["Import java.util.Scanner.","The class still belongs to java.util; import only shortens its written name."]}],"Splitting every tiny method into a new file creates navigation cost without meaningful separation.",[code("mpt-mf-1","Write the import statement for java.util.ArrayList.","import java.util.ArrayList;","java","Imports end with a semicolon.",["Use the fully qualified class name."]),pick("mpt-mf-2","A public class named Invoice should normally be stored in:","Invoice.java",["invoice.txt","Main.java always","Invoice.java","Invoice.class.java"],"Match class and source filename exactly.",["Java's public-class filename convention applies."]),code("mpt-mf-3","Write a package declaration for package school.records.","package school.records;","java","A package declaration is the first source statement.",["Use dotted package components."]),pick("mpt-mf-4","What does import do?","Allows a shorter name for a type from another package",["Copies the class into the file","Allows a shorter name for a type from another package","Creates an object","Runs the compiler"],"Ownership does not change.",["The class remains in its original package."]),pick("mpt-mf-5","Which responsibility belongs in a PriceCalculator class?","Calculating an order total",["Drawing every screen","Calculating an order total","Handling every unrelated task","Storing all global variables"],"Choose one cohesive role.",["The class name and behavior align."])],[code("mpt-mf-r1","Import java.util.List.","import java.util.List;","java","Use the full package path.",["The statement ends with a semicolon."]),pick("mpt-mf-r2","Which file should contain public class Customer?","Customer.java",["customer.txt","Customer.java","Main.java","Customer.class"],"Case matters.",["The filename matches the public class."]),pick("mpt-mf-r3","Where does a package declaration appear?","Before imports and the class declaration",["Inside main","After every method","Before imports and the class declaration","Only in compiled files"],"It identifies the source file's package.",["It is the first source declaration."])]);

const eventsThreads=c("mpt-events-threads","Events, GUIs & Threads","Respond to external events while protecting shared state and the user interface.",["interfaces","exceptions"],["event-driven-programming","gui-events","threads","race-conditions"],["Event-driven programs wait for events such as clicks, input, or messages and dispatch handler code. The program's flow is determined by event arrival rather than one uninterrupted sequence in main. Handlers should remain small and delegate real work to testable classes.","Threads allow tasks to make progress concurrently. Shared mutable state creates race conditions when outcomes depend on timing. Coordinate access or redesign to reduce sharing; never block a GUI event thread with long work."],["Register a handler for the event source.","Keep slow work off the GUI event thread.","Shared updates must be coordinated or avoided."],[{problem:"A button starts a long download.",steps:["The click handler starts background work.","Completion posts a small UI update back to the UI thread."]},{problem:"Two threads increment one counter.",steps:["Read-modify-write can interleave.","Protect the update or use an atomic abstraction."]}],"Threads do not automatically make a program faster; coordination and task structure determine the result.",[pick("mpt-et-1","What determines control flow in an event-driven program?","The arrival of events",["Only source-file order","The arrival of events","The compiler version","Field visibility"],"The program waits and responds.",["Handlers are dispatched for events."]),pick("mpt-et-2","Where should a long network request run in a GUI program?","Off the UI event thread",["Inside every paint call","Off the UI event thread","Before the program starts only","In a getter"],"Avoid freezing input and drawing.",["Background work preserves responsiveness."]),pick("mpt-et-3","What is a race condition?","A result that depends on thread timing",["A syntax error","A result that depends on thread timing","A private method","A constructor overload"],"Shared operations interleave unpredictably.",["Different schedules can produce different results."]),code("mpt-et-4","Create a Thread variable named worker from an existing Runnable named task.","Thread worker = new Thread(task);","java","Pass the Runnable to the Thread constructor.",["The thread is created but not yet started."]),code("mpt-et-5","Start the Thread stored in worker.","worker.start();","java","Call start rather than run directly.",["start schedules work on a new thread."])],[pick("mpt-et-r1","Calling worker.run() directly does what?","Runs the method on the current thread",["Starts a new thread","Runs the method on the current thread","Stops every thread","Creates a GUI"],"Only start requests a new thread.",["A normal method call stays on the caller thread."]),pick("mpt-et-r2","Why keep event handlers small?","To preserve responsiveness and delegate testable work",["To remove all objects","To preserve responsiveness and delegate testable work","To avoid methods","To make fields public"],"Handlers coordinate rather than contain the whole application.",["Small handlers reduce blocking and coupling."]),pick("mpt-et-r3","Two threads mutate one unsynchronized counter. The main risk is:","A race condition",["Inheritance","A race condition","A package error","Method overloading"],"Timing affects the compound update.",["Updates can be lost."])]);

const networking=c("mpt-networking","Simple Networking & Course Synthesis","Define a protocol boundary and combine objects, validation, testing, and concurrency.",["threads","multi-file-programs"],["client-server","network-protocols","resource-lifecycle","maintainable-systems"],["A client initiates communication with a server at an address and port. Both sides need a protocol: agreed message structure, order, encoding, and failure behavior. A connection carrying bytes does not explain their meaning by itself.","Network programs must expect delay, partial input, disconnection, and invalid messages. Keep protocol parsing separate from domain behavior, close resources deliberately, and test the pure parts without requiring a live network."],["A protocol defines message meaning and order.","Validate data received across a network boundary.","Separate transport, parsing, and domain logic for maintainability."],[{problem:"Design a score-update message.",steps:["Choose a clear format such as SCORE 42.","Validate the command and integer before changing state."]},{problem:"Test a networked calculator.",steps:["Test parsing and calculation as ordinary methods.","Use a smaller integration test for the socket boundary."]}],"A successful connection does not prove the peers understand the same protocol.",[pick("mpt-ne-1","What identifies a service on a host in simple client-server networking?","A port",["A constructor","A port","A private field","An assertion only"],"The host locates the machine; this value locates the service.",["Clients connect to an address and port."]),pick("mpt-ne-2","What must client and server share?","An agreed protocol",["The same object reference","An agreed protocol","Every source file","One call stack"],"Bytes require agreed meaning.",["The protocol defines message structure and sequence."]),pick("mpt-ne-3","Where should message parsing live?","In a focused boundary component",["Scattered through every class","In a focused boundary component","Only in field declarations","Inside equals"],"Separate transport format from domain rules.",["A focused parser is easier to test and change."]),pick("mpt-ne-4","Which failure should network code expect?","A connection can end before a complete message arrives",["Input is always complete","A connection can end before a complete message arrives","Every message is valid","Timing is fixed"],"Remote boundaries are unreliable.",["Code must handle partial input and disconnection."]),pick("mpt-ne-5","Which design is most maintainable?","Socket code delegates validated requests to domain objects",["One giant method does everything","Socket code delegates validated requests to domain objects","All fields are public","Errors are ignored"],"Separate responsibilities.",["Transport and domain behavior evolve independently."])],[pick("mpt-ne-r1","A protocol primarily defines:","The meaning and order of exchanged messages",["Object memory addresses","The meaning and order of exchanged messages","Class inheritance","GUI colors"],"Communication needs shared rules.",["Both sides interpret bytes consistently."]),pick("mpt-ne-r2","Which part can be unit-tested without a live server?","The message parser",["Only the network cable","The message parser","The remote computer","The port number itself"],"Separate pure logic from transport.",["Known strings can test parsing deterministically."]),pick("mpt-ne-r3","Which course idea helps prevent invalid network input from corrupting state?","Encapsulation with validation",["Public fields","Encapsulation with validation","Ignoring exceptions","Reference equality"],"Route changes through protected operations.",["Domain methods preserve invariants."])]);

classes.sections[0].teaches.push("modern-programming");
const tests=(prefix:string,questions:MathQuestion[])=>questions.map((question,index)=>({...question,id:`${prefix}-${index+1}`}));

export const cisc3115:MathCourse={id:"cisc3115",code:"CISC 3115",title:"Introduction to Modern Programming Techniques",description:"A second programming course centered on reliable object-oriented Java, multi-file design, testing, recursion, event-driven programs, threads, and simple networking.",prerequisites:["java-foundations"],sources:[{title:"Brooklyn College CISC 3115 catalog description",url:"https://websql.brooklyn.cuny.edu/courses/ShowCourse.do?crs_num=3115&div=U&dsc=CISC."},{title:"Brooklyn College CISC 3115 weekly syllabus",url:"https://static.brooklyn.edu/web/aca_naturalsciences_cis/Syllabus.pdf"}],units:[
  unit("mpt-unit1","I · Classes & Valid Objects",[classes,constructors],tests("mpt-u1",[code("x","Declare a private int field named level.","private int level;","java","Write one field declaration.",["The field belongs to each object."]),code("x","Construct a Game object in variable game.","Game game = new Game();","java","Use new and the matching constructor.",["Store the reference in game."]),code("x","Inside a constructor parameterized by String id, assign it to field id.","this.id = id;","java","Distinguish parameter and field.",["this.id is the field."]),pick("x","Two separately constructed objects have:","Separate instance state",["One shared instance state","Separate instance state","No fields","Only static fields"],"Each construction creates an object.",["Instance fields belong to each object."]),pick("x","A constructor includes which return type?","None",["void","The class type","None","int"],"Its name signals construction.",["Constructors have no return type."])])),
  unit("mpt-unit2","II · Object-Oriented Design",[encapsulation,staticAggregation],tests("mpt-u2",[pick("x","Which design protects a nonnegative quantity?","Private field plus validated methods",["Public field","Private field plus validated methods","Static local variable","No constructor"],"Control every mutation.",["Encapsulation supports invariants."]),code("x","Write a getter getLevel for int field level.","public int getLevel() { return level; }","java","Return the field.",["The getter does not mutate state."]),code("x","Declare a private static int named total.","private static int total;","java","Mark class-wide state static.",["One total is shared."]),pick("x","A Playlist contains Songs. This is:","Aggregation",["Inheritance","Aggregation","Overriding","Recursion"],"Playlist has Songs.",["Has-a is aggregation."]),pick("x","In UML, + typically means:","Public",["Private","Public","Static","Abstract only"],"The symbol denotes visibility.",["Plus is public."])])),
  unit("mpt-unit3","III · Inheritance & Polymorphism",[inheritance,polymorphism,objectMethods],tests("mpt-u3",[code("x","Declare Cat as a subclass of Animal.","public class Cat extends Animal { }","java","Use extends.",["Cat is-an Animal."]),pick("x","Same method signature in subclass means:","Overriding",["Overloading","Overriding","Aggregation","Throwing"],"The inherited behavior is specialized.",["Same signature gives an override."]),pick("x","Superclass reference holding subclass object selects overrides by:","Actual object type",["Filename","Actual object type","Reference variable name","Package length"],"This is dynamic binding.",["The object's class chooses the implementation."]),pick("x","For objects, == checks:","Reference identity",["Value equality always","Reference identity","toString output","Field count"],"Use equals for logical equality.",["== asks whether references select the same object."]),code("x","Append value to StringBuilder b.","b.append(value);","java","Call append on b.",["The builder is mutated."])])),
  unit("mpt-unit4","IV · Failures & Abstraction",[exceptions,abstraction],tests("mpt-u4",[code("x","Throw IllegalArgumentException with message \"invalid\".","throw new IllegalArgumentException(\"invalid\");","java","Construct and throw it.",["The statement ends with a semicolon."]),pick("x","Which block is intended for cleanup?","finally",["try","catch","finally","extends"],"It runs after try/catch.",["finally supports cleanup."]),code("x","Declare interface RunnableThing with void run().","public interface RunnableThing { void run(); }","java","Declare the capability.",["No method body is required."]),pick("x","An abstract class can be instantiated directly?","No",["Yes","No","Only twice","Only if private"],"It may be incomplete.",["Use a concrete subclass."]),pick("x","Catching and ignoring every exception does what?","Hides failures",["Guarantees correctness","Hides failures","Creates tests","Preserves every invariant"],"Lost evidence makes diagnosis harder.",["Silent catches are not recovery."])])),
  unit("mpt-unit5","V · Recursion & Verification",[recursion,testing],tests("mpt-u5",[output("x","sum(4)=4+sum(3), with sum(0)=0. What is returned?","10",["4","6","10","16"],"Expand to the base case.",["4+3+2+1=10."]),pick("x","A recursive call must:","Move toward a reachable base case",["Create an object","Move toward a reachable base case","Use a loop too","Be static"],"Guarantee termination.",["A decreasing measure is typical."]),pick("x","Best tests for inclusive range 5..9 include:","4,5,9,10",["6,7","4,5,9,10","5 only","100 only"],"Use boundaries and neighbors.",["These distinguish accepted from rejected values."]),pick("x","A regression test protects:","A previously fixed behavior",["Only new features","A previously fixed behavior","Compiler installation","Class naming"],"Keep the reproducing case.",["The defect should not return."]),code("x","Assert that size is nonnegative.","assert size >= 0;","java","Write the invariant as a boolean assertion.",["The assertion detects a violated assumption."])])),
  unit("mpt-unit6","VI · Programs Beyond One Call Stack",[multifile,eventsThreads,networking],tests("mpt-u6",[code("x","Import java.util.Map.","import java.util.Map;","java","Use the full type name.",["Imports precede the class."]),pick("x","Long GUI work belongs:","Off the UI event thread",["Inside the paint method","Off the UI event thread","In a getter","In every constructor"],"Preserve responsiveness.",["Use background work."]),pick("x","A result depending on thread timing is:","A race condition",["Overloading","A race condition","Aggregation","A package"],"Shared updates can interleave.",["Different schedules change the result."]),pick("x","Client and server need an agreed:","Protocol",["Superclass","Protocol","Object reference","GUI"],"Messages need shared meaning.",["The protocol defines the exchange."]),pick("x","A maintainable network program separates:","Transport, parsing, and domain logic",["Nothing","Transport, parsing, and domain logic","Every statement into one class","Only comments"],"Keep boundaries testable.",["Responsibilities can change independently."])])),
]};
